insert into public.subject_exams (subject_id, title, description, duration_minutes, config, questions, created_by_name) values
  ('mat7', 'Evaluación de práctica 1', 'Simulacro con contenidos de las unidades 1 (nube y virtualización), 2 (bases de datos y SQL) y 5 (redes y direccionamiento IP): 20 preguntas de opción múltiple con una sola respuesta correcta. Cada respuesta correcta suma 0,5 y las incorrectas no restan.', 40, '{"pointsPerQuestion": 0.5, "fpPenaltyEnabled": false, "fpPenalty": 0.2, "fnPenaltyEnabled": false, "fnPenalty": 0.1, "passMode": "percent", "passValue": 60}'::jsonb, '[{"id": "inf2-ev-01-q01", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "Según el NIST, ¿en qué modelo de servicio el proveedor de la nube es responsable del acceso a las herramientas y los servicios de desarrollo que se usan para proporcionar las aplicaciones?", "options": [{"text": "Software como servicio (SaaS)"}, {"text": "Plataforma como servicio (PaaS)"}, {"text": "Infraestructura como servicio (IaaS)"}, {"text": "Nube híbrida"}], "correct": 1}, {"id": "inf2-ev-01-q02", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "Un servicio de correo electrónico y Office 365 provisto por Internet, en el que el usuario solo necesita aportar sus datos, es un ejemplo de:", "options": [{"text": "Infraestructura como servicio (IaaS)"}, {"text": "Plataforma como servicio (PaaS)"}, {"text": "Software como servicio (SaaS)"}, {"text": "Virtualización de servidores"}], "correct": 2}, {"id": "inf2-ev-01-q03", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿En qué modelo de servicio el proveedor es responsable del acceso a los equipos de la red, los servicios de red virtualizados y el soporte de infraestructura de la red?", "options": [{"text": "Nube comunitaria"}, {"text": "Plataforma como servicio (PaaS)"}, {"text": "Software como servicio (SaaS)"}, {"text": "Infraestructura como servicio (IaaS)"}], "correct": 3}, {"id": "inf2-ev-01-q04", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "\"El cliente elige cuándo iniciar y dejar de usar el servicio, sin ninguna interacción directa con el proveedor.\" ¿Qué característica de la nube describe?", "options": [{"text": "Pooling de recursos"}, {"text": "Servicio medido"}, {"text": "Elasticidad rápida"}, {"text": "Autoservicio bajo demanda"}], "correct": 3}, {"id": "inf2-ev-01-q05", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "¿Quién propuso el modelo relacional para sistemas de bases de datos en 1970?", "options": [{"text": "Chris Date"}, {"text": "La empresa Oracle"}, {"text": "Peter Chen"}, {"text": "El Dr. E. F. Codd"}], "correct": 3}, {"id": "inf2-ev-01-q06", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "El modelo entidad-interrelación (E/R), también llamado modelo conceptual de datos, fue propuesto por:", "options": [{"text": "IBM, junto con el lenguaje SEQUEL"}, {"text": "ANSI, como estándar de SQL"}, {"text": "Peter Chen, en 1976"}, {"text": "E. F. Codd, en 1970"}], "correct": 2}, {"id": "inf2-ev-01-q07", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En el modelo relacional, el término \"relación\" es sinónimo de:", "options": [{"text": "Tabla"}, {"text": "Clave ajena"}, {"text": "Interrelación entre dos entidades"}, {"text": "Consulta guardada"}], "correct": 0}, {"id": "inf2-ev-01-q08", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "¿Qué característica tiene una clave primaria?", "options": [{"text": "Siempre hace referencia a una columna de otra tabla"}, {"text": "Identifica de manera única cada fila: no admite valores duplicados y debe contener un valor"}, {"text": "Es un puntero físico a la ubicación de la fila en el disco"}, {"text": "Puede repetirse si las filas tienen otros datos distintos"}], "correct": 1}, {"id": "inf2-ev-01-q09", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "SELECT, INSERT, UPDATE, DELETE y MERGE forman parte del:", "options": [{"text": "DCL (lenguaje de control de datos)"}, {"text": "Control de transacciones"}, {"text": "DDL (lenguaje de definición de datos)"}, {"text": "DML (lenguaje de manipulación de datos)"}], "correct": 3}, {"id": "inf2-ev-01-q10", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "CREATE, ALTER, DROP, RENAME, TRUNCATE y COMMENT forman parte del:", "options": [{"text": "DDL (lenguaje de definición de datos)"}, {"text": "DCL (lenguaje de control de datos)"}, {"text": "DML (lenguaje de manipulación de datos)"}, {"text": "Control de transacciones"}], "correct": 0}, {"id": "inf2-ev-01-q11", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Qué sentencias otorgan o quitan derechos de acceso a la base de datos (DCL)?", "options": [{"text": "INSERT y DELETE"}, {"text": "COMMIT y ROLLBACK"}, {"text": "GRANT y REVOKE"}, {"text": "CREATE y DROP"}], "correct": 2}, {"id": "inf2-ev-01-q12", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "COMMIT, ROLLBACK y SAVEPOINT se usan para:", "options": [{"text": "El control de transacciones: gestionar los cambios hechos con sentencias DML"}, {"text": "Definir la estructura de las tablas"}, {"text": "Otorgar permisos a los usuarios"}, {"text": "Ordenar las filas de una consulta"}], "correct": 0}, {"id": "inf2-ev-01-q13", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "Una impresora que se conecta directamente a la red, y no a través de una PC, actúa como:", "options": [{"text": "Un host"}, {"text": "Un punto de acceso inalámbrico"}, {"text": "Un dispositivo periférico"}, {"text": "Un router"}], "correct": 0}, {"id": "inf2-ev-01-q14", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "Una red que interconecta dispositivos en un área limitada (una casa, un edificio, un campus), administrada por una única organización y con alto ancho de banda, es una:", "options": [{"text": "MAN"}, {"text": "WAN"}, {"text": "LAN"}, {"text": "SAN"}], "correct": 2}, {"id": "inf2-ev-01-q15", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Qué característica corresponde a una WAN?", "options": [{"text": "Abarca un área geográfica pequeña, como un edificio"}, {"text": "Conecta dispositivos dentro del alcance de una persona"}, {"text": "Siempre ofrece enlaces más rápidos que una LAN"}, {"text": "Interconecta redes LAN en áreas geográficas extensas y, por lo general, la administran proveedores de servicios"}], "correct": 3}, {"id": "inf2-ev-01-q16", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Con cuántos dispositivos Bluetooth más puede conectarse un dispositivo Bluetooth?", "options": [{"text": "Hasta quince"}, {"text": "Hasta siete"}, {"text": "Con cualquier cantidad"}, {"text": "Hasta dos"}], "correct": 1}, {"id": "inf2-ev-01-q17", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Qué tipo de red está diseñada para admitir servidores de archivos y proporcionar almacenamiento, recuperación y replicación de datos?", "options": [{"text": "PAN (red de área personal)"}, {"text": "MAN (red de área metropolitana)"}, {"text": "SAN (red de área de almacenamiento)"}, {"text": "WLAN (LAN inalámbrica)"}], "correct": 2}, {"id": "inf2-ev-01-q18", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Qué característica tiene la dirección MAC de un host?", "options": [{"text": "Es una dirección lógica que asigna el administrador de red"}, {"text": "Es la dirección física: se graba en la NIC al fabricarla y no cambia aunque el host se mueva de red"}, {"text": "Cambia cada vez que el host se conecta a otra red"}, {"text": "Tiene 32 bits escritos en notación decimal punteada"}], "correct": 1}, {"id": "inf2-ev-01-q19", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Por qué la dirección IP se conoce como \"dirección lógica\"?", "options": [{"text": "Porque viene grabada de fábrica en la tarjeta de red"}, {"text": "Porque se asigna lógicamente según la ubicación del host en la red, igual que una dirección postal"}, {"text": "Porque nunca cambia, como una huella digital"}, {"text": "Porque está formada por seis grupos de valores hexadecimales"}], "correct": 1}, {"id": "inf2-ev-01-q20", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Cuántos bits tienen una dirección IPv4 y una dirección IPv6?", "options": [{"text": "IPv4 tiene 32 bits e IPv6 tiene 128 bits"}, {"text": "IPv4 tiene 32 bits e IPv6 tiene 64 bits"}, {"text": "IPv4 tiene 64 bits e IPv6 tiene 128 bits"}, {"text": "Las dos tienen 128 bits"}], "correct": 0}]'::jsonb, 'Generador de evaluaciones'),
  ('mat7', 'Evaluación de práctica 2', 'Simulacro con contenidos de las unidades 1 (nube y virtualización), 2 (bases de datos y SQL) y 5 (redes y direccionamiento IP): 20 preguntas de opción múltiple con una sola respuesta correcta. Cada respuesta correcta suma 0,5 y las incorrectas no restan.', 40, '{"pointsPerQuestion": 0.5, "fpPenaltyEnabled": false, "fpPenalty": 0.2, "fnPenaltyEnabled": false, "fnPenalty": 0.1, "passMode": "percent", "passValue": 60}'::jsonb, '[{"id": "inf2-ev-02-q01", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "\"Para el cliente, el pool de recursos parece ilimitado y las solicitudes de un nuevo servicio se resuelven rápidamente.\" ¿Qué característica de la nube describe?", "options": [{"text": "Amplio acceso a la red"}, {"text": "Servicio medido"}, {"text": "Elasticidad rápida"}, {"text": "Autoservicio bajo demanda"}], "correct": 2}, {"id": "inf2-ev-02-q02", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "\"El proveedor puede medir el uso e informarlo al cliente, tanto por transparencia como para facturar.\" ¿Qué característica de la nube describe?", "options": [{"text": "Servicio medido"}, {"text": "Elasticidad rápida"}, {"text": "Amplio acceso a la red"}, {"text": "Pooling de recursos"}], "correct": 0}, {"id": "inf2-ev-02-q03", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué significa \"pooling de recursos\" en la computación en la nube?", "options": [{"text": "El servicio está disponible desde muchos tipos de dispositivos y redes"}, {"text": "El cliente compra por adelantado toda la infraestructura que va a usar"}, {"text": "Cada cliente recibe servidores físicos dedicados solo para él"}, {"text": "El proveedor crea un pool de recursos y los adjudica dinámicamente a cada nueva solicitud, en lugar de dedicar servidores a clientes determinados"}], "correct": 3}, {"id": "inf2-ev-02-q04", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué modelo de nube ofrece aplicaciones y servicios a disposición de la población en general, gratis o con pago según el uso, a través de Internet?", "options": [{"text": "Nube privada"}, {"text": "Nube híbrida"}, {"text": "Nube pública"}, {"text": "Nube comunitaria"}], "correct": 2}, {"id": "inf2-ev-02-q05", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "¿Qué es una clave ajena?", "options": [{"text": "Una columna que no puede repetirse dentro de su propia tabla"}, {"text": "Una columna que nunca puede quedar nula"}, {"text": "Una columna (o conjunto de columnas) que hace referencia a una clave primaria o única; su valor debe existir en esa clave o ser nulo"}, {"text": "Un puntero físico que indica dónde está guardada otra tabla"}], "correct": 2}, {"id": "inf2-ev-02-q06", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "Según el material, ¿qué significa que un campo tenga un valor nulo?", "options": [{"text": "Que el valor es cero"}, {"text": "Que el dato tiene un error de tipo"}, {"text": "Que el valor no está disponible, no está asignado, es desconocido o no es aplicable"}, {"text": "Que el valor es un espacio en blanco"}], "correct": 2}, {"id": "inf2-ev-02-q07", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En las convenciones del modelo de entidad-relación de Oracle, ¿cómo se marca un atributo obligatorio?", "options": [{"text": "Con una almohadilla: #"}, {"text": "Con un asterisco: *"}, {"text": "Con una almohadilla entre paréntesis: (#)"}, {"text": "Con la letra \"o\""}], "correct": 1}, {"id": "inf2-ev-02-q08", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En las convenciones del modelo de entidad-relación de Oracle, ¿cómo se marca el identificador único (UID) principal?", "options": [{"text": "Con una almohadilla: #"}, {"text": "Con la letra \"o\""}, {"text": "Con un asterisco: *"}, {"text": "Con una almohadilla entre paréntesis: (#)"}], "correct": 0}, {"id": "inf2-ev-02-q09", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "Elegir qué columnas de una tabla devuelve una consulta SELECT se denomina:", "options": [{"text": "Selección"}, {"text": "Concatenación"}, {"text": "Proyección"}, {"text": "Unión"}], "correct": 2}, {"id": "inf2-ev-02-q10", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Qué cláusula restringe las filas que devuelve una consulta?", "options": [{"text": "ORDER BY"}, {"text": "DISTINCT"}, {"text": "FROM"}, {"text": "WHERE"}], "correct": 3}, {"id": "inf2-ev-02-q11", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Qué hace la palabra clave DISTINCT en SELECT DISTINCT department_id, job_id FROM employees?", "options": [{"text": "Elimina los duplicados solo de department_id"}, {"text": "Ordena el resultado por department_id"}, {"text": "Devuelve solo las filas con valores nulos"}, {"text": "Elimina las filas duplicadas: devuelve las combinaciones distintas de las dos columnas"}], "correct": 3}, {"id": "inf2-ev-02-q12", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "Si un empleado tiene salary = 1000, ¿qué valor muestra para él la expresión 12*salary+100?", "options": [{"text": "1200"}, {"text": "12100"}, {"text": "13200"}, {"text": "112000"}], "correct": 1}, {"id": "inf2-ev-02-q13", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "Una compañía que da acceso seguro a sus proveedores y contratistas externos a datos de la empresa está usando:", "options": [{"text": "Una extranet"}, {"text": "Una intranet"}, {"text": "Una red punto a punto"}, {"text": "Una PAN"}], "correct": 0}, {"id": "inf2-ev-02-q14", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Cuál es una desventaja de las redes punto a punto (P2P)?", "options": [{"text": "Todos los datos quedan en un servidor de archivos central"}, {"text": "Necesitan servidores dedicados para funcionar"}, {"text": "Solo funcionan con más de diez PC"}, {"text": "No hay administración ni seguridad centralizadas: cada usuario es responsable de sus propios recursos"}], "correct": 3}, {"id": "inf2-ev-02-q15", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "Con una conexión DSL, ¿por qué se puede hablar por teléfono sin desconectarse de Internet?", "options": [{"text": "Porque DSL se conecta por satélite"}, {"text": "Porque la línea telefónica se divide en canales y uno de ellos se usa para la voz"}, {"text": "Porque DSL usa el cable coaxial de la televisión"}, {"text": "Porque la llamada viaja por el canal de subida"}], "correct": 1}, {"id": "inf2-ev-02-q16", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Qué requisito tiene el acceso a Internet satelital?", "options": [{"text": "Un cable coaxial de televisión"}, {"text": "Una línea de vista despejada hacia el satélite"}, {"text": "Cobertura de telefonía celular"}, {"text": "Estar cerca de la oficina central de la compañía telefónica"}], "correct": 1}, {"id": "inf2-ev-02-q17", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "El hecho de que haya varias rutas que conducen a un mismo destino, para que la red sea tolerante a fallas, se denomina:", "options": [{"text": "Escalabilidad"}, {"text": "Calidad de servicio (QoS)"}, {"text": "Latencia"}, {"text": "Redundancia"}], "correct": 3}, {"id": "inf2-ev-02-q18", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Cómo se escribe habitualmente una dirección IPv6?", "options": [{"text": "Como 32 valores hexadecimales agrupados en ocho bloques de cuatro, separados por dos puntos"}, {"text": "Como cuatro octetos decimales separados por puntos"}, {"text": "Como seis grupos de dos valores hexadecimales separados por guiones"}, {"text": "Como 128 dígitos binarios sin separadores"}], "correct": 0}, {"id": "inf2-ev-02-q19", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "En una dirección IPv4, ¿qué es un octeto?", "options": [{"text": "Un grupo de 8 bits, que se escribe como un número decimal"}, {"text": "Un grupo de 8 direcciones IP"}, {"text": "Cada uno de los 8 bloques de una dirección"}, {"text": "Un grupo de 4 bits escrito en hexadecimal"}], "correct": 0}, {"id": "inf2-ev-02-q20", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "Un host tiene la dirección 192.168.18.57 con la máscara 255.255.255.0. ¿Cuál es la porción de red?", "options": [{"text": "192.168"}, {"text": "192.168.18"}, {"text": "57"}, {"text": "192"}], "correct": 1}]'::jsonb, 'Generador de evaluaciones'),
  ('mat7', 'Evaluación de práctica 3', 'Simulacro con contenidos de las unidades 1 (nube y virtualización), 2 (bases de datos y SQL) y 5 (redes y direccionamiento IP): 20 preguntas de opción múltiple con una sola respuesta correcta. Cada respuesta correcta suma 0,5 y las incorrectas no restan.', 40, '{"pointsPerQuestion": 0.5, "fpPenaltyEnabled": false, "fpPenalty": 0.2, "fnPenaltyEnabled": false, "fnPenalty": 0.1, "passMode": "percent", "passValue": 60}'::jsonb, '[{"id": "inf2-ev-03-q01", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "Una nube creada para el uso exclusivo de una comunidad específica, con necesidades funcionales personalizadas (por ejemplo, organizaciones de salud que deben cumplir leyes como HIPAA), es una:", "options": [{"text": "Nube comunitaria"}, {"text": "Nube privada"}, {"text": "Nube pública"}, {"text": "Nube híbrida"}], "correct": 0}, {"id": "inf2-ev-03-q02", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué modelo de nube consta de dos o más nubes que siguen siendo objetos separados, pero están conectadas a través de una única arquitectura?", "options": [{"text": "Nube comunitaria"}, {"text": "Centro de datos privado"}, {"text": "Nube híbrida"}, {"text": "Nube pública"}], "correct": 2}, {"id": "inf2-ev-03-q03", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "Una nube destinada a una organización o entidad específica, como el gobierno, que puede configurarse con la red privada de la organización, es una:", "options": [{"text": "Nube híbrida"}, {"text": "Nube privada"}, {"text": "Nube pública"}, {"text": "Nube comunitaria"}], "correct": 1}, {"id": "inf2-ev-03-q04", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "Con el modelo de \"pago según el consumo\" de la nube, ¿qué pasa con los gastos de la organización?", "options": [{"text": "Los gastos de capital se transforman en gastos operativos"}, {"text": "Desaparecen todos los gastos de almacenamiento"}, {"text": "La organización tiene que invertir en más servidores propios"}, {"text": "Los gastos operativos se transforman en gastos de capital"}], "correct": 0}, {"id": "inf2-ev-03-q05", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En un diagrama de relaciones, ¿qué indica la \"pata de gallo\"?", "options": [{"text": "Un elemento opcional (\"puede ser\")"}, {"text": "Un grado de \"uno o más\""}, {"text": "Un elemento obligatorio (\"debe ser\")"}, {"text": "Un grado de \"uno y sólo uno\""}], "correct": 1}, {"id": "inf2-ev-03-q06", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En un diagrama de relaciones, ¿qué indica una línea con guiones?", "options": [{"text": "Un grado de \"uno o más\""}, {"text": "Un elemento opcional: \"puede ser\""}, {"text": "Un grado de \"uno y sólo uno\""}, {"text": "Un elemento obligatorio: \"debe ser\""}], "correct": 1}, {"id": "inf2-ev-03-q07", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En un diagrama entidad-interrelación (E/R), ¿qué representan los rombos?", "options": [{"text": "Las claves primarias"}, {"text": "Las interrelaciones entre entidades"}, {"text": "Los atributos"}, {"text": "Las entidades"}], "correct": 1}, {"id": "inf2-ev-03-q08", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En un diagrama E/R, ¿qué elementos nunca se enlazan directamente con una línea?", "options": [{"text": "Un atributo con una interrelación"}, {"text": "Una entidad con una interrelación"}, {"text": "Un atributo con una entidad"}, {"text": "Una entidad con otra entidad"}], "correct": 3}, {"id": "inf2-ev-03-q09", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "Un alias de columna que contiene espacios, como Annual Salary, debe escribirse:", "options": [{"text": "Entre comillas dobles: \"Annual Salary\""}, {"text": "Siempre precedido de AS y sin comillas"}, {"text": "Sin comillas: los espacios están permitidos"}, {"text": "Entre comillas simples: ''Annual Salary''"}], "correct": 0}, {"id": "inf2-ev-03-q10", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Cuál es el operador de concatenación en SQL de Oracle?", "options": [{"text": "&& (doble ampersand)"}, {"text": "** (doble asterisco)"}, {"text": "|| (dos barras verticales)"}, {"text": "+ (más)"}], "correct": 2}, {"id": "inf2-ev-03-q11", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "La condición WHERE salary BETWEEN 2500 AND 3500 devuelve los salarios:", "options": [{"text": "Entre 2500 y 3500, sin incluir los límites"}, {"text": "Mayores que 3500 o menores que 2500"}, {"text": "Iguales a 2500 o a 3500"}, {"text": "Entre 2500 y 3500, incluyendo ambos límites"}], "correct": 3}, {"id": "inf2-ev-03-q12", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Qué apellidos devuelve WHERE last_name LIKE ''_o%''?", "options": [{"text": "Los que contienen el texto \"_o\""}, {"text": "Los que terminan en o"}, {"text": "Los que tienen la letra o como segundo carácter"}, {"text": "Los que empiezan con o"}], "correct": 2}, {"id": "inf2-ev-03-q13", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Qué requisito de seguridad garantiza que la información no se alteró durante la transmisión desde el origen hasta el destino?", "options": [{"text": "La confidencialidad"}, {"text": "La escalabilidad"}, {"text": "La disponibilidad"}, {"text": "La integridad"}], "correct": 3}, {"id": "inf2-ev-03-q14", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "El tiempo que tardan los datos en desplazarse desde el origen hasta el destino se denomina:", "options": [{"text": "Ancho de banda"}, {"text": "Full-duplex"}, {"text": "Latencia"}, {"text": "Redundancia"}], "correct": 2}, {"id": "inf2-ev-03-q15", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "Las radios bidireccionales de la Policía, en las que no se puede escuchar mientras se presiona el botón para hablar, funcionan en modo:", "options": [{"text": "Full-duplex"}, {"text": "Half-duplex"}, {"text": "Broadcast"}, {"text": "Simplex"}], "correct": 1}, {"id": "inf2-ev-03-q16", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Cuál es la longitud máxima de un cable UTP usado para datos?", "options": [{"text": "100 metros"}, {"text": "500 metros"}, {"text": "2 kilómetros"}, {"text": "10 metros"}], "correct": 0}, {"id": "inf2-ev-03-q17", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Por qué se trenzan los pares de cables en el par trenzado?", "options": [{"text": "Para poder transmitir pulsos de luz"}, {"text": "Para que no haga falta conectarlo a tierra"}, {"text": "Para que el cable sea más barato de fabricar"}, {"text": "Para protegerlos del crosstalk: los campos magnéticos opuestos de los dos cables se anulan entre sí"}], "correct": 3}, {"id": "inf2-ev-03-q18", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Cuál de estas direcciones pertenece a un rango privado?", "options": [{"text": "192.169.1.1"}, {"text": "172.32.1.1"}, {"text": "172.20.5.4"}, {"text": "11.0.0.1"}], "correct": 2}, {"id": "inf2-ev-03-q19", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Cuál es la máscara de subred predeterminada de una dirección de clase B?", "options": [{"text": "255.255.255.0"}, {"text": "255.0.0.0"}, {"text": "255.255.255.255"}, {"text": "255.255.0.0"}], "correct": 3}, {"id": "inf2-ev-03-q20", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Para qué se usan las direcciones IPv4 de clase D?", "options": [{"text": "Para multicast"}, {"text": "Para redes pequeñas de proveedores de Internet"}, {"text": "Para redes extensas de compañías grandes"}, {"text": "Para pruebas experimentales"}], "correct": 0}]'::jsonb, 'Generador de evaluaciones'),
  ('mat7', 'Evaluación de práctica 4', 'Simulacro con contenidos de las unidades 1 (nube y virtualización), 2 (bases de datos y SQL) y 5 (redes y direccionamiento IP): 20 preguntas de opción múltiple con una sola respuesta correcta. Cada respuesta correcta suma 0,5 y las incorrectas no restan.', 40, '{"pointsPerQuestion": 0.5, "fpPenaltyEnabled": false, "fpPenalty": 0.2, "fnPenaltyEnabled": false, "fnPenalty": 0.1, "passMode": "percent", "passValue": 60}'::jsonb, '[{"id": "inf2-ev-04-q01", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "Según el material, ¿cuál es la relación entre computación en la nube y virtualización?", "options": [{"text": "Son sinónimos y se pueden usar de manera intercambiable"}, {"text": "La virtualización es la base de la nube: la nube separa la aplicación del hardware y la virtualización separa el sistema operativo del hardware"}, {"text": "La nube es la base de la virtualización: sin la nube no se puede virtualizar"}, {"text": "La virtualización separa la aplicación del sistema operativo y la nube separa la red del hardware"}], "correct": 1}, {"id": "inf2-ev-04-q02", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué es un hipervisor?", "options": [{"text": "Un modelo de servicio en la nube definido por el NIST"}, {"text": "El conjunto de teclado, monitor y mouse de un servidor"}, {"text": "Un programa, firmware o hardware que suma una capa de abstracción sobre el hardware físico para crear máquinas virtuales"}, {"text": "Un servidor dedicado que ejecuta un único sistema operativo"}], "correct": 2}, {"id": "inf2-ev-04-q03", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "En los servidores dedicados, ¿qué se conoce como \"punto único de falla\"?", "options": [{"text": "Que no hay un usuario sentado junto al servidor"}, {"text": "Que los servidores pasan mucho tiempo inactivos y malgastan energía"}, {"text": "Que varias máquinas virtuales comparten el mismo hardware"}, {"text": "Que cuando falla un componente, el servicio que presta ese servidor deja de estar disponible"}], "correct": 3}, {"id": "inf2-ev-04-q04", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué se conoce como \"proliferación de servidores\"?", "options": [{"text": "Crear servidores virtuales a pedido en la nube"}, {"text": "Que un servicio deja de estar disponible cuando falla un componente"}, {"text": "Consolidar varios servidores físicos en uno con hipervisor"}, {"text": "Tener muchos servidores dedicados infrautilizados, inactivos durante largos períodos, que malgastan energía y ocupan espacio"}], "correct": 3}, {"id": "inf2-ev-04-q05", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "¿Qué es una entidad débil?", "options": [{"text": "Una entidad que tiene más de una clave candidata"}, {"text": "Una entidad con pocos atributos"}, {"text": "Una entidad sin clave primaria propia, que depende de una entidad fuerte; su clave es el discriminante más la clave primaria de la entidad fuerte"}, {"text": "Una entidad que no participa en ninguna interrelación"}], "correct": 2}, {"id": "inf2-ev-04-q06", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "¿Cuál es la diferencia entre clave candidata y clave primaria?", "options": [{"text": "Son lo mismo: una entidad solo puede tener una clave"}, {"text": "La candidata identifica la tabla y la primaria identifica la base de datos"}, {"text": "Todas las claves posibles son candidatas; la que elige el diseñador para identificar cada entidad es la primaria"}, {"text": "La candidata puede tener valores repetidos y la primaria no"}], "correct": 2}, {"id": "inf2-ev-04-q07", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "Un préstamo bancario pertenece como máximo a un cliente, y un mismo cliente puede tener varios préstamos. ¿Qué razón de cardinalidad hay entre CLIENTE y PRESTAMO?", "options": [{"text": "Muchas a muchas (N:M)"}, {"text": "Una a una (1:1)"}, {"text": "No se puede modelar con una interrelación"}, {"text": "Una a muchas (1:N)"}], "correct": 3}, {"id": "inf2-ev-04-q08", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "Si un préstamo puede tener varios titulares y cada cliente puede tener varios préstamos, ¿qué razón de cardinalidad hay entre CLIENTE y PRESTAMO?", "options": [{"text": "Una a una (1:1)"}, {"text": "Muchas a una (N:1)"}, {"text": "Muchas a muchas (N:M)"}, {"text": "Una a muchas (1:N)"}], "correct": 2}, {"id": "inf2-ev-04-q09", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "En la condición LIKE, ¿qué representa el símbolo _ (guion bajo)?", "options": [{"text": "Un dígito numérico"}, {"text": "Exactamente un carácter cualquiera"}, {"text": "Cero o más caracteres"}, {"text": "Un espacio en blanco"}], "correct": 1}, {"id": "inf2-ev-04-q10", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Qué condición devuelve los empleados que no tienen supervisor (manager_id sin valor)?", "options": [{"text": "WHERE manager_id = 0"}, {"text": "WHERE manager_id IS NULL"}, {"text": "WHERE manager_id = ''''"}, {"text": "WHERE manager_id = NULL"}], "correct": 1}, {"id": "inf2-ev-04-q11", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "¿Qué filas devuelve WHERE job_id = ''SA_REP'' OR job_id = ''AD_PRES'' AND salary > 15000?", "options": [{"text": "Todos los SA_REP, más los AD_PRES que ganan más de 15000 (AND se evalúa antes que OR)"}, {"text": "Solo los AD_PRES, ganen lo que ganen"}, {"text": "Ninguna: la condición da error sin paréntesis"}, {"text": "Solo los SA_REP o AD_PRES que ganan más de 15000"}], "correct": 0}, {"id": "inf2-ev-04-q12", "type": "multiple_choice", "topic": "Unidad 2 · SQL", "prompt": "En un ORDER BY en orden ascendente, ¿dónde aparecen los valores nulos?", "options": [{"text": "Al final"}, {"text": "No aparecen: se excluyen del resultado"}, {"text": "Al principio"}, {"text": "Depende del orden en que se cargaron"}], "correct": 0}, {"id": "inf2-ev-04-q13", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Qué tipo de cable se necesita para conectar un puerto de switch con un puerto de router?", "options": [{"text": "Un cable directo, porque son dispositivos diferentes"}, {"text": "Un cable coaxial con conector BNC"}, {"text": "Un cable cruzado, porque son dispositivos similares"}, {"text": "Un cable de fibra monomodo"}], "correct": 0}, {"id": "inf2-ev-04-q14", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Cuál es la diferencia entre la fibra óptica multimodo y la monomodo?", "options": [{"text": "La multimodo usa láser y llega a 100 km; la monomodo usa LED y llega a 2 km"}, {"text": "La multimodo transmite electricidad y la monomodo transmite luz"}, {"text": "No hay diferencia de distancia: solo cambia el color del revestimiento"}, {"text": "La multimodo tiene un núcleo más grueso, suele usar LED y llega a unos 2 km; la monomodo tiene un núcleo muy fino, usa láser y llega a unos 100 km"}], "correct": 3}, {"id": "inf2-ev-04-q15", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿Cuántas capas tienen el modelo OSI y el modelo TCP/IP?", "options": [{"text": "OSI tiene siete capas y TCP/IP tiene cuatro"}, {"text": "Los dos tienen siete capas"}, {"text": "OSI tiene cinco capas y TCP/IP tiene tres"}, {"text": "OSI tiene cuatro capas y TCP/IP tiene siete"}], "correct": 0}, {"id": "inf2-ev-04-q16", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "¿En qué capa del modelo TCP/IP operan los protocolos TCP y UDP?", "options": [{"text": "Aplicación"}, {"text": "Acceso a la red"}, {"text": "Internet"}, {"text": "Transporte"}], "correct": 3}, {"id": "inf2-ev-04-q17", "type": "multiple_choice", "topic": "Unidad 5 · Redes", "prompt": "En el proceso de encapsulación, ¿en qué se transforma cada paquete de la capa de red al pasar por la capa de enlace de datos?", "options": [{"text": "En un segmento, con números de puerto y de secuencia"}, {"text": "En una trama, que contiene la dirección física e información de corrección de errores"}, {"text": "En datos de la capa de aplicación"}, {"text": "En bits que se transmiten uno a uno"}], "correct": 1}, {"id": "inf2-ev-04-q18", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "Cuando un servidor DHCP asigna una dirección IP a un host por un período específico, ese proceso se denomina:", "options": [{"text": "Resolución de nombres"}, {"text": "Concesión"}, {"text": "Encapsulación"}, {"text": "Direccionamiento estático"}], "correct": 1}, {"id": "inf2-ev-04-q19", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "Si una PC con Windows no logra comunicarse con el servidor DHCP, se asigna automáticamente una dirección link-local (APIPA). ¿En qué rango está?", "options": [{"text": "169.254.0.0 a 169.254.255.255"}, {"text": "10.0.0.0 a 10.255.255.255"}, {"text": "192.168.0.0 a 192.168.255.255"}, {"text": "127.0.0.0 a 127.255.255.255"}], "correct": 0}, {"id": "inf2-ev-04-q20", "type": "multiple_choice", "topic": "Unidad 5 · Direccionamiento IP", "prompt": "¿Qué hace el DNS?", "options": [{"text": "Asigna direcciones IP automáticamente a los hosts"}, {"text": "Traduce direcciones IP a direcciones MAC"}, {"text": "Resuelve nombres de host y direcciones URL a direcciones IP"}, {"text": "Identifica el dispositivo que se usa para salir a otra red"}], "correct": 2}]'::jsonb, 'Generador de evaluaciones'),
  ('mat7', 'Evaluación de práctica 5', 'Simulacro con contenidos de las unidades 1 (nube y virtualización), 2 (bases de datos y SQL) y 5 (redes y direccionamiento IP): 20 preguntas de opción múltiple con una sola respuesta correcta. Cada respuesta correcta suma 0,5 y las incorrectas no restan.', 40, '{"pointsPerQuestion": 0.5, "fpPenaltyEnabled": false, "fpPenalty": 0.2, "fnPenaltyEnabled": false, "fnPenalty": 0.1, "passMode": "percent", "passValue": 60}'::jsonb, '[{"id": "inf2-ev-05-q01", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "En la mayoría de los servidores no hace falta KVM. ¿Qué significa KVM en este contexto?", "options": [{"text": "Un modelo de nube definido por el NIST"}, {"text": "Un servicio de Amazon para crear instancias virtuales a pedido"}, {"text": "Teclado, monitor (video) y mouse, que no se necesitan porque los usuarios y administradores se conectan por la red"}, {"text": "La memoria compartida por todas las máquinas virtuales de un hipervisor"}], "correct": 2}, {"id": "inf2-ev-05-q02", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué ventaja de la virtualización reduce los costos mensuales de alimentación y refrigeración y ayuda a tener una huella de carbono más pequeña?", "options": [{"text": "Menor consumo de energía"}, {"text": "Soporte de tecnologías heredadas"}, {"text": "Simplificación de prototipos"}, {"text": "Aprovisionamiento acelerado de servidores"}], "correct": 0}, {"id": "inf2-ev-05-q03", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Por qué la virtualización mejora la recuperación tras un desastre?", "options": [{"text": "Porque las máquinas virtuales no pueden fallar"}, {"text": "Porque duplica cada servidor físico en el sitio de recuperación"}, {"text": "Porque elimina la necesidad de hacer copias de seguridad"}, {"text": "Porque abstrae el hardware: el sitio de recuperación ya no necesita hardware idéntico al del entorno de producción"}], "correct": 3}, {"id": "inf2-ev-05-q04", "type": "multiple_choice", "topic": "Unidad 1 · Nube y virtualización", "prompt": "¿Qué ejemplo da el material de un servicio que permite aprovisionar dinámicamente servidores virtualizados a pedido?", "options": [{"text": "Amazon Elastic Compute Cloud (Amazon EC2)"}, {"text": "Un Windows Server instalado en hardware específico"}, {"text": "La ley HIPAA"}, {"text": "Office 365"}], "correct": 0}, {"id": "inf2-ev-05-q05", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "Al pasar del modelo E/R al modelo relacional, ¿en qué se transforma una interrelación N:M entre dos entidades?", "options": [{"text": "En una columna agregada en una de las dos tablas"}, {"text": "En una tabla intermedia, asociada a las tablas de las dos entidades mediante interrelaciones 1:N"}, {"text": "En nada: las interrelaciones N:M se descartan"}, {"text": "En una sola tabla que fusiona las dos entidades"}], "correct": 1}, {"id": "inf2-ev-05-q06", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "Al pasar del modelo E/R al modelo relacional, una entidad débil se transforma en una tabla cuyos campos son:", "options": [{"text": "Solamente la clave primaria de la entidad fuerte"}, {"text": "Las claves primarias de todas las tablas de la base de datos"}, {"text": "Los atributos de la entidad fuerte, sin los de la débil"}, {"text": "Los atributos de la entidad débil más la clave primaria de la entidad fuerte con la que se asocia"}], "correct": 3}, {"id": "inf2-ev-05-q07", "type": "multiple_choice", "topic": "Unidad 2 · Modelo relacional y E/R", "prompt": "En una interrelación 1:N con integridad referencial y propagación de eliminaciones, ¿qué pasa si se elimina un registro de la tabla del lado 1?", "options": [{"text": "Los registros del lado N quedan apuntando a una clave que ya no existe"}, {"text": "También se eliminan los registros asociados de la tabla del lado